(()=>{
 const $=id=>document.getElementById(id),dialog=$('report-dialog');let generation=0,current=null,previewURL=null;
 function snapshot(day){const es=entries(day),showValues=state.settings.includeReportValues!==false;return{day,dateLabel:dayLabel(day),name:state.profile?.name||'Meu dia de trabalho',photo:state.profile?.photo||null,showValues,count:es.length,urban:es.filter(e=>e.area==='urban').length,rural:es.filter(e=>e.area==='rural').length,total:showValues?sum(es):null,rows:groupEntries(es).map(r=>({...r,total:showValues?r.total:null}))}}
 function round(ctx,x,y,w,h,r,fill){ctx.beginPath();ctx.roundRect(x,y,w,h,r);ctx.fillStyle=fill;ctx.fill()}
 function text(ctx,value,x,y,size,color='#18372f',weight=500,align='left',maxWidth){ctx.fillStyle=color;ctx.textAlign=align;weight=weight>=650?700:weight;let font=size;ctx.font=`${weight} ${font}px sans-serif`;if(maxWidth){while(ctx.measureText(String(value)).width>maxWidth&&font>4){font-=.5;ctx.font=`${weight} ${font}px sans-serif`}}ctx.fillText(String(value),x,y)}
 function photoImage(source){return new Promise(resolve=>{if(typeof source!=='string'||!/^data:image\/(jpeg|png|webp);base64,/.test(source)){resolve(null);return}const image=new Image(),timer=setTimeout(()=>resolve(null),2000);image.onload=()=>{clearTimeout(timer);resolve(image)};image.onerror=()=>{clearTimeout(timer);resolve(null)};image.src=source})}
 async function paint(model){const canvas=document.createElement('canvas'),side=Math.min(4096,Math.max(2000,1200+model.rows.length*70));canvas.width=canvas.height=side;const ctx=canvas.getContext('2d');if(!ctx)throw Error('Imagem indisponível');ctx.scale(side/2000,side/2000);ctx.fillStyle='#e7eedf';ctx.fillRect(0,0,2000,2000);const glow=ctx.createRadialGradient(300,100,10,300,100,1800);glow.addColorStop(0,'#f5f8f0');glow.addColorStop(1,'#e0ebd6');ctx.fillStyle=glow;ctx.fillRect(0,0,2000,2000);
 ctx.shadowColor='#163f351a';ctx.shadowBlur=50;round(ctx,70,70,1860,1860,70,'#ffffff');ctx.shadowBlur=0;round(ctx,70,70,1860,490,70,'#163f35');ctx.fillStyle='#163f35';ctx.fillRect(70,300,1860,260);
 // Minimal OS Fácil clipboard mark, rendered locally and kept crisp in the export.
 ctx.strokeStyle='#d9edb5';ctx.lineWidth=6;ctx.beginPath();ctx.roundRect(151,135,47,60,10);ctx.stroke();ctx.beginPath();ctx.moveTo(162,166);ctx.lineTo(173,177);ctx.lineTo(190,156);ctx.stroke();text(ctx,'OS FÁCIL',225,180,33,'#eef6e5',650);text(ctx,'SEU TRABALHO CONTA',1845,180,20,'#bcd4bc',500,'right');
 text(ctx,model.name,150,325,72,'#ffffff',650,'left',1400);text(ctx,'Fechamento do dia',153,385,29,'#c9dcc5');round(ctx,150,427,980,65,25,'#ffffff16');text(ctx,model.dateLabel,177,471,30,'#eef6e5',500,'left',925);
 const avatar=await photoImage(model.photo);ctx.save();ctx.beginPath();ctx.arc(1745,340,100,0,Math.PI*2);ctx.clip();ctx.fillStyle='#d9edb5';ctx.fillRect(1645,240,200,200);if(avatar)ctx.drawImage(avatar,1645,240,200,200);else text(ctx,Array.from(model.name)[0]?.toLocaleUpperCase('pt-BR')||'O',1745,367,82,'#163f35',650,'center');ctx.restore();
 text(ctx,model.showValues?'TOTAL DA DIÁRIA':'SERVIÇOS REALIZADOS',150,655,24,'#63765f',650);text(ctx,model.showValues?money(model.total):`${model.count} OS`,145,751,84,'#163f35',650,'left',1500);if(model.showValues)text(ctx,`${model.count} OS realizadas`,1845,738,30,'#63765f',500,'right');
 ctx.strokeStyle='#e2e9dc';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(150,800);ctx.lineTo(1850,800);ctx.stroke();text(ctx,'SERVIÇOS DO DIA',150,857,23,'#63765f',650);text(ctx,'QTD.',model.showValues?1420:1845,857,23,'#63765f',650,'right');if(model.showValues)text(ctx,'VALOR',1845,857,23,'#63765f',650,'right');
 const available=820,rowHeight=Math.min(110,available/Math.max(1,model.rows.length));if(!model.rows.length)text(ctx,'Nenhuma OS registrada nesta data.',150,992,34,'#70816b');
 model.rows.forEach((r,i)=>{const y=890+i*rowHeight,fs=Math.min(32,rowHeight*.37);if(i%2===0)round(ctx,125,y-8,1750,rowHeight-5,Math.min(16,rowHeight/5),'#f3f6ef');text(ctx,`OS ${r.code} · ${r.name}`,150,y+rowHeight*.38,fs,'#244333',600,'left',model.showValues?1140:1450);text(ctx,r.area==='urban'?'Urbano':'Rural',150,y+rowHeight*.77,Math.min(23,rowHeight*.26),'#687d62');text(ctx,r.quantity,model.showValues?1420:1845,y+rowHeight*.56,Math.min(34,rowHeight*.4),'#244333',600,'right',180);if(model.showValues)text(ctx,money(r.total),1845,y+rowHeight*.56,Math.min(32,rowHeight*.38),'#244333',600,'right',360)});
 ctx.strokeStyle='#e2e9dc';ctx.beginPath();ctx.moveTo(150,1750);ctx.lineTo(1850,1750);ctx.stroke();round(ctx,150,1780,650,68,25,'#edf4e3');text(ctx,`Urbano ${model.urban}  ·  Rural ${model.rural}`,177,1826,28,'#35573b',500,'left',595);text(ctx,`${model.count} serviços no total`,1845,1826,28,'#35573b',500,'right',850);text(ctx,model.showValues?'Cada serviço, um resultado.':'Relatório compartilhado sem valores financeiros.',150,1887,23,'#6b7f65',500,'left',1500);text(ctx,'OS Fácil',1845,1887,24,'#35573b',650,'right');
 const blob=await new Promise((resolve,reject)=>canvas.toBlob(b=>b?resolve(b):reject(Error('Falha ao gerar PNG')),'image/png'));return{blob,width:side,height:side,model}}
 function cleanup(){generation++;current=null;if(previewURL)URL.revokeObjectURL(previewURL);previewURL=null;$('report-preview').removeAttribute('src');$('report-preview').hidden=true;$('report-actions').hidden=true}
 async function open(day){cleanup();const token=generation;$('report-status').textContent='Preparando sua diária em imagem…';dialog.showModal();try{const result=await paint(snapshot(day));if(token!==generation)return;const file=new File([result.blob],`OS-Facil-${day}.png`,{type:'image/png'});current={...result,file};previewURL=URL.createObjectURL(result.blob);$('report-preview').src=previewURL;$('report-preview').hidden=false;$('report-actions').hidden=false;$('report-status').textContent=`${result.model.dateLabel} · imagem quadrada${result.model.showValues?' · com valores':' · sem valores'}`;let native=false;try{native=!!navigator.share&&!!navigator.canShare?.({files:[file]})}catch{}$('share-image').hidden=!native}catch{$('report-status').textContent='Não foi possível gerar a imagem. Feche e tente novamente.'}}
 function download(){if(!current||!previewURL)return;const a=document.createElement('a');a.href=previewURL;a.download=current.file.name;document.body.append(a);a.click();a.remove();notify('Imagem pronta para salvar nos downloads.')}
 $('close-report').onclick=()=>dialog.close();dialog.addEventListener('close',cleanup);$('download-image').onclick=download;
 $('share-image').onclick=async()=>{if(!current)return;const button=$('share-image');button.disabled=true;try{await navigator.share({files:[current.file],title:`OS Fácil • ${current.model.dateLabel}`,text:`Diária de ${current.model.name} • ${current.model.dateLabel}`})}catch(e){if(e.name!=='AbortError'){notify('O navegador não conseguiu compartilhar. Use Baixar imagem PNG.')}}finally{button.disabled=false}};
 window.OSReport={open,snapshot,paint};
})();
